for n in ['project','source','binding','launcher-history','output']:p.add_argument('--'+n,type=pathlib.Path,required=True)
a=p.parse_args();load=lambda p:json.loads(p.read_bytes());cpath=a.project/'cad/assembly/intake_components.json';c=load(cpath);b=load(a.binding);history=load(a.launcher_history);source=load(a.source);s=source['final'];n=s['note'];d=s['chassis'];nc=load(a.project/'sim/acquisition/free-planar-config.json')['model'];ac=load(a.project/'sim/actuation/config.json')
